/**
 * Galerija — the gallery of medresa.me/galerija, its heading and introduction.
 *
 * All 44 photographs of the source gallery, in its order (01–44; `source` is the
 * original upload path), converted to static assets (EXIF-upright, long edge
 * ≤ 2400px). None were exact duplicates. The source has no captions (only file
 * numbers), so none are shown; `alt` describes what each photograph shows, for
 * screen readers only. `blur` is a tiny placeholder shown while it loads.
 *
 *   story    the opening journey: 18 photographs in art-directed rows
 *   archive  the other 26, in source order (two views of one room kept apart),
 *            revealed by „Prikaži cijelu galeriju“
 */
export type Photo = {
  id: string;
  src: string;
  width: number;
  height: number;
  alt: string;
  source: string;
  blur: string;
};

export type RowKind =
  | "threshold"
  | "cinema"
  | "wide"
  | "wideRight"
  | "pair"
  | "pairPortrait"
  | "pairSquare"
  | "portrait"
  | "closing";
export type Row = { kind: RowKind; ids: readonly string[] };

export const galerija = {
  title: "Galerija",
  /** As the source sets it (in capitals); only the quotation marks follow this site. */
  heading: "GALERIJA KOMPLEKSA MEDRESE „MEHMED FATIH“",
  intro:
    "Dobro došli u prostor u kojem se znanje, vjera i ljepota susreću. Ove fotografije prikazuju cjelinu našeg kompleksa: učionice, džamiju, dvorišta i prostore koji svakodnevno svjedoče predanosti znanju i odgoju. Svaki kadar nosi priču o trudu, zajedništvu i duhovnom miru koji ispunjava naše hodnike.",
  more: "Prikaži cijelu galeriju",
};

